class Solution {
public:
    string countAndSay(int n) {
        string cur = "1";
        for (int line = 1; line < n; line++) {
            string next;
            int i = 0;
            while (i < (int)cur.size()) {
                int j = i;
                while (j < (int)cur.size() && cur[j] == cur[i]) j++;
                next += to_string(j - i) + cur[i];
                i = j;
            }
            cur = next;
        }
        return cur;
    }
};
